import { useState } from "react";
import { Heading } from "@servicenow/react-components/Heading";
import { ButtonIconic } from "@servicenow/react-components/ButtonIconic";
interface Props {
  title: string;
  initialCount: number;
}

const Counter = ({ title, initialCount }: Props) => {
  const [count, setCount] = useState(initialCount);

  const add = (factor = 1) => {
    setCount(count + factor);
  };

  return (
    <div className="centered-container">
      <Heading level={2} label={title} />
      <Heading level={3} label={String(count)} />
      <div>
        <ButtonIconic
          icon="minus-outline"
          onClicked={() => add(-1)}
          disabled={count === 0}
        />
        <ButtonIconic icon="plus-outline" onClicked={() => add()} />
      </div>
    </div>
  );
};

export default Counter;
